import{_ as a,o as e,c as t,ag as n}from"./chunks/framework.CmaAMB6e.js";const k=JSON.parse('{"title":"01 · Hello World 与项目结构","description":"","frontmatter":{"概念":"Hello World 与项目结构","技能":"harmony","阶段":"1-基础层","状态":"⬜未开始","更新日期":"2026-07-08T00:00:00.000Z","前置":"无","耗时":"约 1 小时"},"headers":[],"relativePath":"harmony/concepts/01-hello-world.md","filePath":"harmony/concepts/01-hello-world.md","lastUpdated":1784195062000}'),o={name:"harmony/concepts/01-hello-world.md"};function l(i,s,r,d,p,c){return e(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="_01-·-hello-world-与项目结构" tabindex="-1">01 · Hello World 与项目结构 <a class="header-anchor" href="#_01-·-hello-world-与项目结构" aria-label="Permalink to &quot;01 · Hello World 与项目结构&quot;">​</a></h1><blockquote><p><strong>前置</strong>：无 · <strong>预计</strong>：约 1 小时</p></blockquote><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>「Hello World」是进入任何语言的第一步：跑通最小可运行程序，确认工具链就绪。但它的真正价值在于让你看清一个平台的<strong>项目结构</strong>--入口在哪、构建工具是什么、依赖怎么管理、源码如何组织。理解了这些，后续每个概念才有落脚点。</p><p>在 鸿蒙 中，四个核心要素对应如下：<strong>入口</strong>是 <code>@Entry struct</code>，<strong>项目清单</strong>是 <code>oh-package.json5</code>，<strong>构建工具</strong>是 hvigor，<strong>运行命令</strong>是 DevEco Studio 点 Run 或 <code>hvigorw assembleHap</code>。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><p>用 DevEco Studio 创建 Empty Ability 项目。</p><p>入口与根组件：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// entry/src/main/ets/pages/Index.ets</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@Entry                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 标记页面入口</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@Component            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 声明组件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">struct Index {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 类比 React 的 render / Vue 的 template</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        Text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Hello World&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>项目结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>├── entry/                        # 主模块</span></span>
<span class="line"><span>│   └── src/main/</span></span>
<span class="line"><span>│       ├── ets/pages/Index.ets   # 页面入口（ArkTS）</span></span>
<span class="line"><span>│       ├── resources/            # 资源</span></span>
<span class="line"><span>│       └── module.json5          # 模块配置（类比 package.json）</span></span>
<span class="line"><span>├── build-profile.json5           # 构建配置</span></span>
<span class="line"><span>└── oh-package.json5              # 依赖管理（ohpm）</span></span></code></pre></div><p>构建运行：DevEco Studio 点 Run，或命令行 <code>hvigorw assembleHap</code>。</p><p>ArkTS 的 <code>@Entry @Component struct</code> + <code>build()</code> 是固定写法，类似 Vue 的 SFC 但用 struct。DevEco 模拟器需登录华为账号；ArkTS 是 TS 的子集，部分 JS 特性不支持。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>鸿蒙</strong>：ArkTS 的 <code>@Entry @Component struct</code> + <code>build()</code> 是固定写法，类似 Vue 的 SFC 但用 struct。陷阱：DevEco 模拟器需登录华为账号；ArkTS 是 TS 的子集，部分 JS 特性不支持。</li><li><strong>共性陷阱</strong>：移动端都要在模拟器/真机上运行，比浏览器启动慢，首次配置环境耗时较长，预留耐心。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：跑通一次 Hello World，确认环境就绪</li><li><strong>进阶</strong>：在 Hello World 基础上，改为显示「Hello, 你的名字」，并加一个按钮点击修改名字（接触最基础的状态与事件）</li><li><strong>综合</strong>：用一句话总结项目入口文件 <code>Index.ets</code> 的职责</li></ol><blockquote><p>用 <code>/practice harmony Hello World</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端 (Vite/React)</th><th>鸿蒙 (ArkTS)</th></tr></thead><tbody><tr><td><code>main.jsx</code> 挂载根组件</td><td><code>@Entry</code> 标记页面入口</td></tr><tr><td><code>package.json</code> 依赖与脚本</td><td><code>oh-package.json5</code> 依赖管理</td></tr><tr><td><code>App.jsx</code> 根组件</td><td><code>@Component struct</code> + <code>build()</code></td></tr><tr><td>Vite 构建打包</td><td>hvigor 构建（<code>assembleHap</code>）</td></tr><tr><td><code>npm run dev</code> 启动开发服务器</td><td>DevEco Studio 点 Run / <code>hvigorw</code></td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://developer.harmonyos.com/cn/documentation" target="_blank" rel="noreferrer">鸿蒙 HarmonyOS 开发文档</a></li></ul>`,22)])])}const g=a(o,[["render",l]]);export{k as __pageData,g as default};
